package ultra.downloads;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=28,qualifiers="w480dp-h800dp-mdpi") @LooperMode(LooperMode.Mode.PAUSED)
public class DL23RegressionTest {
 Context c;
 @Before public void setup()throws Exception{c=RuntimeEnvironment.getApplication();c.setTheme(android.R.style.Theme_Material_NoActionBar);app.revanced.extension.shared.utils.Utils.testContext=c;Art.network=false;Library.prefs(c).edit().clear().commit();PlaylistIndex.invalidateCache();Field f=Library.class.getDeclaredField("items");f.setAccessible(true);f.set(null,null);new File(c.getFilesDir(),"ultra_downloads_v1.json").delete();Library.wiping=false;}
 Library.Item item(int n,String state)throws Exception{String id=String.format("T%010d",n);Library.Item i=Library.add(c,id,"Song "+n);i.artist="Artist";i.album="Album";i.state=state;return i;}
 Object get(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 void set(Object o,String n,Object v)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}
 void render(DownloadsScreen s)throws Exception{Method m=DownloadsScreen.class.getDeclaredMethod("render",boolean.class);m.setAccessible(true);m.invoke(s,true);}
 void layout(Activity a){View d=a.getWindow().getDecorView();d.measure(View.MeasureSpec.makeMeasureSpec(480,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(800,View.MeasureSpec.EXACTLY));d.layout(0,0,480,800);Shadows.shadowOf(Looper.getMainLooper()).idle();}
 DownloadsScreen open(Activity a){a.setTheme(android.R.style.Theme_Material_NoActionBar);FrameLayout mount=new FrameLayout(a);a.setContentView(mount);return new DownloadsScreen(a,mount,new Intent());}
 @Test public void sixtyUnmatchedAreLiveReadOnlyAndNeverSelfMatch()throws Exception{JSONArray matched=new JSONArray();for(int n=0;n<65;n++){Library.Item i=item(n,"done");if(n<5)matched.put(new JSONObject().put("id",i.id));}item(100,"paused");item(101,"done").hidden=true;Library.save(c);JSONObject local=new JSONObject().put("Known",matched);Library.prefs(c).edit().putString("ultra_local_playlists",local.toString()).commit();String before=Library.prefs(c).getString("ultra_local_playlists","");assertEquals(60,UnmatchedDownloads.items(c).size());assertEquals(60,PlaylistIndex.total(c,UnmatchedDownloads.ID));int[] membership=LocalAudio.membership(c,Library.all(c));assertEquals(5,membership[0]);assertEquals(60,membership[1]);assertEquals(before,Library.prefs(c).getString("ultra_local_playlists",""));matched.put(new JSONObject().put("id","T0000000005"));Library.prefs(c).edit().putString("ultra_local_playlists",new JSONObject().put("Known",matched).toString()).commit();assertEquals(59,UnmatchedDownloads.ids(c).size());Library.remove(c,Library.get(c,"T0000000006"));assertEquals(58,UnmatchedDownloads.items(c).size());}
 @Test public void virtualListLongPressAndMenusSurviveScrollAndSelectAll()throws Exception{for(int n=0;n<60;n++)item(n,"done");Library.save(c);Activity a=Robolectric.buildActivity(Activity.class).setup().get();DownloadsScreen s=open(a);render(s);layout(a);ListView list=(ListView)get(s,"virtualList");assertEquals(60,list.getCount());View first=list.getAdapter().getView(0,null,list);assertEquals(ViewGroup.FOCUS_BLOCK_DESCENDANTS,((ViewGroup)first).getDescendantFocusability());View more=first.findViewWithTag("row_action");assertEquals("More options",more.getContentDescription());assertFalse(more.isFocusable());assertTrue(first.performLongClick());assertTrue((Boolean)get(s,"selectionMode"));assertEquals(1,((Set<?>)get(s,"selectedKeys")).size());Method select=DownloadsScreen.class.getDeclaredMethod("selectAll");select.setAccessible(true);select.invoke(s);assertEquals(60,((Set<?>)get(s,"selectedKeys")).size());s.destroy();}
 @Test public void artistsAlbumsAndPlaylistsHaveSeparateMenuAndLongPressSelection()throws Exception{item(0,"done");Library.save(c);Activity a=Robolectric.buildActivity(Activity.class).setup().get();DownloadsScreen s=open(a);for(String tab:new String[]{"Artists","Albums","Playlists"}){set(s,"tab",tab);set(s,"group","");set(s,"selectionMode",false);((Set<?>)get(s,"selectedKeys")).clear();render(s);LinearLayout rows=(LinearLayout)get(s,"rows");View row=null;for(int n=0;n<rows.getChildCount();n++){View v=rows.getChildAt(n);if(v.getTag()!=null&&v.getTag().toString().startsWith(tab.equals("Playlists")?"playlist:":"group:")){row=v;break;}}assertNotNull(tab,row);boolean menu=false;ViewGroup g=(ViewGroup)row;for(int n=0;n<g.getChildCount();n++)if("More options".contentEquals(g.getChildAt(n).getContentDescription()==null?"":g.getChildAt(n).getContentDescription()))menu=true;assertTrue(tab+" menu",menu);assertTrue(tab+" select",row.performLongClick());assertEquals(1,((Set<?>)get(s,"selectedKeys")).size());}s.destroy();}
}
